    case 'lock-other-equipment': plan.target = 'energy-isolator'; plan.beats = [beat('lock', '옆 B/C-02 차단장치에 자물쇠를 체결합니다.', { lock: 'wrong-circuit' }), beat('lock', 'B/C-01 차단장치는 여전히 ON · 대상 불일치', {}, 1200)]; break;
