    case 'tag-wrong-name': plan.target = 'energy-isolator'; plan.beats = [beat('tag', '다른 작업자의 이름표를 부착합니다.', { tag: 'wrong-name' }), beat('tag', '표지: 김 작업자 · 실제 작업자와 불일치', {}, 1200)]; break;
